(15, 4, 'Perusahaan berbagi/berdiskusi dalam hal pengambilan keputusan tentang hal-hal yang mempengaruhi anda/ berdampak pada anda', '2026-06-22 03:41:30', '2026-06-22 03:53:54', NULL),
