(17, 5, 'Menurut Bapak/Ibu seberapa dengan adanya kegiatan CSR yang dilakukan kepada masyarakat?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(18, 5, 'Menurut Bapak/Ibu seberapa pentingkah melibatkan pemerintah setempat (desa/kecamatan) dan tokoh masyarakat (agama/ pemuda/perempuan) untuk merencanakan program CSR?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(19, 5, 'Menurut Bapak/Ibu seberapa pentingkah mengetahui kejelasan mekanisme/prosedur pelaksanaan program CSR?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(20, 5, 'Menurut Bapak/Ibu seberapa penting kejelasan jenis program CSR?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
