(22, 5, 'Menurut Bapak/Ibu seberapa penting adanya kejelasan/keterbukaan informasi tentang anggaran program CSR?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(23, 5, 'Menurut Bapak/Ibu seberapa penting kesesuaian antara perencanaan program dengan pelaksanaan program CSR?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(24, 5, 'Menurut Bapak/Ibu seberapa penting adanya pendampingan yang intensif dalam pelaksanaan program CSR?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(25, 5, 'Menurut Bapak/Ibu seberapa penting adanya pemantauan dan evaluasi pelaksanaan program CSR secara berkala?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(26, 5, 'Menurut Bapak/Ibu seberapa penting dampak dari program CSR untuk masyarakat (peningkatan pendapatan,kesejahteraan, kerjasama masyarakat, peningkatan keterampilan)?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(27, 5, 'Menurut Bapak/Ibu seberapa penting keberlanjutan manfaat dari program CSR (program tetap berlanjut walaupun sudah tidak mendapatkan dukungan langsung dari perusahaan)?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(28, 5, 'Bagaimana tingkat kepuasan Bapak/Ibu terhadap kinerja kegiatan sosialisasi program CSR yang dilakukan perusahaan kepada masyarakat di lingkup lokasi tempat tinggal anda selama ini?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
(29, 5, 'Bagaimana tingkat kepuasan Bapak/Ibu terhadap kegiatan CSR yang dilakukan oleh PT CAP Station kepada masyarakat?', '2026-06-22 04:12:32', '2026-06-22 04:13:25', NULL),
